    return -(np.exp(p[0]+p[1]*L+p[2]*t+p[3]*t*t)+np.exp(p[4]+p[5]*L+p[6]*t+p[7]*t*t))
def f2b(p):
    return -(np.exp(p[0]+p[1]*L)+ np.exp(p[2]+p[3]*L+p[4]*t+p[5]*t*t))
def f2c(p):
    return -(p[0]*A**p[1] + np.exp(p[2]+p[3]*L+p[4]*t+p[5]*t*t))
